args.command:
cd /workspace; export HOME=/tmp/nshprobe
time ./executable --norc -c 'sleep 2 & echo after' 
echo ===
time ./executable --norc -c 'sleep 2' 
echo ===
./executable --norc -c 'sleep 0.3 & sleep 0.3 & echo done; wait'
echo ===
./executable --norc -c 'echo one & echo two & echo three'
echo ===
./executable --norc -c 'sleep 0.2 > /tmp/fix/bgtest & echo after; wait; cat /tmp/fix/bgtest'

cd /workspace; export HOME=/tmp/nshprobe
for i in 1 2 3 4 5; do ./executable --norc -c 'true && echo b & echo c' 2>/dev/null | tr '\n' '|'; echo; done
echo ===
for i in 1 2 3; do ./executable --norc -c 'echo hi there & echo c' 2>/dev/null | tr '\n' '|'; echo; done
echo ===
for i in 1 2 3; do ./executable --norc -c 'sleep 0.1 & echo after' 2>/dev/null | tr '\n' '|'; echo; done

cd /workspace; export HOME=/tmp/nshprobe
time ./executable --norc -c 'sleep 0.5 & sleep 0.5 & echo end' 2>&1
echo ===
time ./executable --norc -c 'true && sleep 1 & echo after' 2>&1
echo ===
time ./executable --norc -c 'sleep 0.5 | cat & echo after' 2>&1
echo ===
time ./executable --norc -c 'sleep 1 &' 2>&1

cd /tmp/fix; export HOME=/tmp/nshprobe; NSH=/workspace/executable
printf 'cat <<-EOF\n\t\tindented\n\ttab1\nEOF\n' > /tmp/fix/hd1.sh
$NSH --norc /tmp/fix/hd1.sh >/tmp/o 2>/tmp/e; echo "exit=$?"; echo OUT; sed -n l /tmp/o; echo ERR; cat /tmp/e
echo ======
printf 'cat <<EOF\nunterminated\n' > /tmp/fix/hd4.sh
$NSH --norc /tmp/fix/hd4.sh >/tmp/o 2>/tmp/e; echo "exit=$?"; echo OUT; sed -n l /tmp/o; echo ERR; cat /tmp/e
echo ======
$NSH --norc -c 'cat <<< "here string"' >/tmp/o 2>/tmp/e; echo "exit=$?"; echo OUT; cat /tmp/o; echo ERR; head -6 /tmp/e
echo ======
$NSH --norc -c 'cat <(echo hi)' >/tmp/o 2>/tmp/e; echo "exit=$?"; echo OUT; cat /tmp/o; echo ERR; head -3 /tmp/e
echo ======
$NSH --norc -c 'echo <(echo hi)' >/tmp/o 2>/tmp/e; echo "exit=$?"; echo OUT; cat /tmp/o; echo ERR; head -3 /tmp/e
